{
  "findings": [
    {
      "check_id": "CKV_AZURE_224",
      "title": "SQL ledger is not enabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "This trading database may contain financial transaction records requiring cryptographic integrity and nonrepudiation, but its ledger capability is not enabled."
    },
    {
      "check_id": "CKV_AZURE_229",
      "title": "SQL database is not zone redundant",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "MEDIUM",
      "explanation": "The database explicitly disables zone redundancy, leaving it more vulnerable to an availability-zone failure. Its S2 service tier also does not support enabling this protection."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"P1\"\n  zone_redundant = true\n  ledger_enabled = true\n}\n",
  "fix_summary": "Enabled SQL ledger and zone redundancy. The database was moved from S2 to the zone-redundancy-capable Premium P1 tier so the availability setting can be applied."
}
